template<typename T>
T inv(T x, T m) {
    return x == 1 ? x : (1 - inv(m % x, x) * m) / x + m;
}

int wtf[256];
uint64_t get_from_table(int i) {
    uint64_t o = 0;
    for (int j = 4; j >= 0; --j) o = o * 92 + wtf[table[i * 5 + j]];
    return o;
}

int main() {
    fast;
    string gc = good_chars();
    for (int i = 0; i < gc.size(); ++i) wtf[gc[i]] = i;

    // vector<int> rt = {1};
    // for(ll i = 1, x = 1; i < mod / 2 + step; ++i) {
    //     x = x * i % mod;
    //     if (i % step == 0) rt.pb(x);
    // }
    // str u;
    // for (int x : rt) {
    //     for (int i = 0, c = x; i < 5; ++i, c /= gc.size()) {
    //         u += gc[c % gc.size()];
    //     }
    // }
    // cout << "string table = \"" << u << "\";" << endl;

    Barrett bt(mod);
    Montgomery mt(mod);
    Montgomery_simd mts(mod);
    fast_mod<uint64_t> fm(mod);
    auto mulmod = [&](uint32_t x, uint32_t y) {
        // return x * y % mod;
        return fm.rem(uint64_t(x) * y);
    };
    auto calc = [&](uint32_t L, uint32_t R) {
        return reduce_prod(L, R + 1, mt, mts);
        // const int B = 4;
        // array<uint32_t, B> ilp; fill(ilp.begin(), ilp.end(), 1);
        // uint32_t i = L;
        // for (; i + B <= R; i += B) {
        //     for (int j = 0; j < B; ++j) {
        //         ilp[j] = mulmod(ilp[j], i + j);
        //     }
        // }
        // for (int j = 0; i <= R; ++i, ++j) ilp[j] = mulmod(ilp[j], i);
        // uint32_t p = 1;
        // for (auto c : ilp) p = mulmod(p, c);
        // return p < mod ? p : p - mod;
    };

    uint64_t z; cin >> z;
    vector<uint64_t> m(z);
    vector<uint32_t> ans(z);
    for (int i = 0; i < z; ++i) {
        uint32_t a; cin >> a;
        int fl = 0;
        if (a > mod / 2) {
            fl = 1;
            a = mod - 1 - a;
        }
        m[i] = uint64_t(a) << 18 | (i << 1) | fl;
    }
    sort(m.begin(), m.end());

    uint64_t pa, pr;
    for (int i = 0; i < z; ++i) {
        uint64_t a = m[i] >> 18, pos = m[i] >> 1 & 131071, fl = m[i] & 1;
        uint64_t st = get_from_table(a / step);
        uint64_t c = a / step * step;
        uint64_t nc = c + step;
        uint64_t v1 = a - c, v2 = nc - a + 30, v3 = i ? a - pa : 1e18;
        uint64_t mn = min({v1, v2, v3});
        if (v1 == mn) {
            st = st * calc(c + 1, a) % mod;
        } else if (v2 == mn){
            st = inv<ll>(get_from_table(a / step + 1), mod);
            st = st * calc(a + 1, nc) % mod;
            st = inv<ll>(st, mod);
        } else if (v3 == mn) {
            st = pr * calc(pa + 1, a) % mod;
        } else assert(0);
        pr = st;
        if (fl) st = inv<ll>(st, mod) * ((mod - a) & 1 ? mod - 1 : 1) % mod;
        ans[pos] = st;
        pa = a;
    }
    for (auto c : ans) cout << c << "\n"; 
}
